// Package repository is the PostgreSQL adapter of the usage domain (queries generated by sqlc).
package repository

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/database"
	"github.com/quixgit/greenops-reliabilix/backend/internal/platform/focus"
	"github.com/quixgit/greenops-reliabilix/backend/internal/usage/domain"
	"github.com/quixgit/greenops-reliabilix/backend/internal/usage/repository/db"
)

type Postgres struct{ Pool *pgxpool.Pool }

const batchSize = 500

// ensurePartitions creates the monthly partitions the records fall into. It must happen before the
// insert: a partition cannot be created later if the DEFAULT partition already holds rows for its range.
func (r Postgres) ensurePartitions(ctx context.Context, recs []focus.Record) error {
	months := map[time.Time]bool{}
	for _, x := range recs {
		months[time.Date(x.ChargePeriodStart.Year(), x.ChargePeriodStart.Month(), 1, 0, 0, 0, 0, time.UTC)] = true
	}
	for m := range months {
		if _, err := r.Pool.Exec(ctx, `SELECT platform.ensure_month_partition('usage.usage_records', 'recorded_at', $1::date)`, m); err != nil {
			return err
		}
	}
	return nil
}

func (r Postgres) Upsert(ctx context.Context, tenantID, projectID, connectionID string, recs []focus.Record) error {
	if len(recs) == 0 {
		return nil
	}
	if err := r.ensurePartitions(ctx, recs); err != nil {
		return err
	}
	var conn *string
	if connectionID != "" {
		conn = &connectionID
	}
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		q := db.New(tx)
		for start := 0; start < len(recs); start += batchSize {
			end := min(start+batchSize, len(recs))
			params := make([]db.UpsertUsageRecordParams, 0, end-start)
			for _, x := range recs[start:end] {
				params = append(params, db.UpsertUsageRecordParams{
					TenantID: tenantID, ProjectID: projectID, ConnectionID: conn, Source: x.Source, Provider: x.Provider,
					ResourceID: x.ResourceID, ResourceType: x.ResourceType, ServiceName: x.ServiceName, ServiceCategory: x.ServiceCategory,
					RegionID: x.RegionID, ConsumedQuantity: x.ConsumedQuantity, ConsumedUnit: x.ConsumedUnit, BilledCost: x.BilledCost,
					EffectiveCost: x.EffectiveCost, Currency: x.Currency, RecordedAt: x.ChargePeriodStart, ChargePeriodEnd: x.ChargePeriodEnd,
				})
			}
			br := q.UpsertUsageRecord(ctx, params)
			var first error
			br.Exec(func(_ int, err error) {
				if err != nil && first == nil {
					first = err
				}
			})
			if err := br.Close(); err != nil && first == nil {
				first = err
			}
			if first != nil {
				return first
			}
		}
		return nil
	})
}

func (r Postgres) List(ctx context.Context, tenantID string, projectID *string, from, to time.Time, limit int) ([]domain.Record, error) {
	out := []domain.Record{}
	err := database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).ListUsage(ctx, db.ListUsageParams{TenantID: tenantID, ProjectID: projectID, FromTs: from, ToTs: to, RowLimit: int32(limit)}) //nolint:gosec // limit is clamped to <= 1000 by the handler
		for _, x := range rows {
			out = append(out, domain.Record{ID: x.ID, ProjectID: x.ProjectID, Provider: x.Provider, Source: x.Source, ResourceID: x.ResourceID,
				ResourceType: x.ResourceType, ServiceName: x.ServiceName, ServiceCategory: x.ServiceCategory, RegionID: x.RegionID,
				ConsumedQuantity: x.ConsumedQuantity, ConsumedUnit: x.ConsumedUnit, BilledCost: x.BilledCost, EffectiveCost: x.EffectiveCost,
				Currency: x.Currency, ChargePeriodStart: x.RecordedAt, ChargePeriodEnd: x.ChargePeriodEnd})
		}
		return err
	})
	return out, err
}

func (r Postgres) DailyAggregates(ctx context.Context, tenantID, projectID string, from, to time.Time) ([]domain.DailyAggregate, error) {
	out := []domain.DailyAggregate{}
	err := database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := db.New(tx).AggregateDaily(ctx, db.AggregateDailyParams{TenantID: tenantID, ProjectID: projectID, FromTs: from, ToTs: to})
		for _, x := range rows {
			out = append(out, domain.DailyAggregate{Provider: x.Provider, ServiceName: x.ServiceName, ServiceCategory: x.ServiceCategory,
				RegionID: x.RegionID, Currency: x.Currency, ConsumedUnit: x.ConsumedUnit, Day: x.Day, Quantity: x.Quantity,
				HasQuantity: x.HasQuantity, BilledCost: x.BilledCost})
		}
		return err
	})
	return out, err
}

// ReplaceTagged rewrites the tagged cost of one source for the days [from, to] (UTC dates, inclusive): what a source reports for a day is the
// whole of it, so a tag value that is gone from the bill is gone here too. An empty list clears the range.
func (r Postgres) ReplaceTagged(ctx context.Context, tenantID, projectID, sourceKey string, from, to time.Time, rows []focus.TaggedCost) error {
	return database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `DELETE FROM usage.tagged_cost WHERE tenant_id = $1 AND project_id = $2 AND source_key = $3 AND day >= $4::date AND day <= $5::date`,
			tenantID, projectID, sourceKey, from, to); err != nil {
			return err
		}
		for start := 0; start < len(rows); start += batchSize {
			end := min(start+batchSize, len(rows))
			b := &pgx.Batch{}
			for _, x := range rows[start:end] {
				b.Queue(`INSERT INTO usage.tagged_cost (tenant_id, project_id, source_key, provider, service_name, currency, day, tag_key, tag_value, billed_cost, effective_cost)
					VALUES ($1, $2, $3, $4, $5, $6, $7::date, $8, $9, $10, $11)
					ON CONFLICT (tenant_id, project_id, source_key, provider, service_name, currency, day, tag_key, tag_value)
					DO UPDATE SET billed_cost = usage.tagged_cost.billed_cost + EXCLUDED.billed_cost, effective_cost = usage.tagged_cost.effective_cost + EXCLUDED.effective_cost, updated_at = now()`,
					tenantID, projectID, sourceKey, x.Provider, x.ServiceName, x.Currency, x.Day, x.TagKey, x.TagValue, x.BilledCost, x.EffectiveCost)
			}
			br := tx.SendBatch(ctx, b)
			for range rows[start:end] {
				if _, err := br.Exec(); err != nil {
					_ = br.Close()
					return err
				}
			}
			if err := br.Close(); err != nil {
				return err
			}
		}
		return nil
	})
}

// poolWhere selects the cost that pays for a cluster: the given services, or every compute cost when none are given.
const poolWhere = `u.tenant_id = $1::uuid AND u.project_id = $2::uuid AND u.recorded_at >= $4 AND u.recorded_at < $5
	AND ((cardinality($3::text[]) = 0 AND u.service_category = 'compute') OR u.service_name = ANY($3::text[]))`

// DailyPool is the cost per day of the services that pay for a cluster, in the reporting currency of the window (the organization's choice, else the
// currency most of the project's cost is billed in). A day without cost is absent.
func (r Postgres) DailyPool(ctx context.Context, tenantID, projectID string, services []string, from, to time.Time) (days []domain.PoolDay, currency string, err error) {
	if services == nil {
		services = []string{}
	}
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `WITH cur AS (SELECT finops.reporting_currency($1::uuid, (SELECT d.currency FROM usage.usage_records d
			    WHERE d.tenant_id = $1::uuid AND d.project_id = $2::uuid AND d.recorded_at >= $4 AND d.recorded_at < $5
			    GROUP BY d.currency ORDER BY sum(abs(d.billed_cost)) DESC, d.currency LIMIT 1))::text AS c),
			g AS (SELECT u.recorded_at::date AS day, u.currency::text AS currency, sum(u.billed_cost) AS cost FROM usage.usage_records u WHERE `+poolWhere+` GROUP BY 1, 2)
			SELECT g.day, COALESCE((SELECT c FROM cur), ''),
			       COALESCE(sum(CASE WHEN g.currency = (SELECT c FROM cur) THEN g.cost ELSE finops.convert_cost(g.cost, g.currency, (SELECT c FROM cur), g.day) END), 0)::float8
			FROM g GROUP BY g.day ORDER BY g.day`, tenantID, projectID, services, from, to)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var d domain.PoolDay
			if err := rows.Scan(&d.Day, &currency, &d.Cost); err != nil {
				return err
			}
			days = append(days, d)
		}
		return rows.Err()
	})
	return
}

// PoolServices lists the billed services that could be paying for a cluster: compute services and the container and Kubernetes services of the
// project, with their cost in the window.
func (r Postgres) PoolServices(ctx context.Context, tenantID, projectID string, from, to time.Time) (out []domain.PoolService, currency string, err error) {
	out = []domain.PoolService{}
	err = database.WithTenantTx(ctx, r.Pool, tenantID, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `WITH cur AS (SELECT finops.reporting_currency($1::uuid, (SELECT d.currency FROM usage.usage_records d
			    WHERE d.tenant_id = $1::uuid AND d.project_id = $2::uuid AND d.recorded_at >= $3 AND d.recorded_at < $4
			    GROUP BY d.currency ORDER BY sum(abs(d.billed_cost)) DESC, d.currency LIMIT 1))::text AS c),
			g AS (SELECT u.service_name, u.recorded_at::date AS day, u.currency::text AS currency, sum(u.billed_cost) AS cost FROM usage.usage_records u
			      WHERE u.tenant_id = $1::uuid AND u.project_id = $2::uuid AND u.recorded_at >= $3 AND u.recorded_at < $4
			        AND (u.service_category = 'compute' OR u.service_name ~* '(kubernetes|container|eks|aks|gke)') GROUP BY 1, 2, 3)
			SELECT g.service_name, COALESCE((SELECT c FROM cur), ''),
			       COALESCE(sum(CASE WHEN g.currency = (SELECT c FROM cur) THEN g.cost ELSE finops.convert_cost(g.cost, g.currency, (SELECT c FROM cur), g.day) END), 0)::float8
			FROM g GROUP BY g.service_name ORDER BY 3 DESC LIMIT 40`, tenantID, projectID, from, to)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var s domain.PoolService
			if err := rows.Scan(&s.Name, &currency, &s.Cost); err != nil {
				return err
			}
			out = append(out, s)
		}
		return rows.Err()
	})
	return
}
